private static extractAndRepairJSON(content: string): any {
  let cleanedContent = content.trim();

  // Remove markdown code blocks if present
  cleanedContent = cleanedContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  try {
    return JSON.parse(cleanedContent);
  } catch (e) {
    // Find the JSON structure inside the answer
    const jsonMatch = cleanedContent.match(/(\[[\s\S]*\]|\{[\s\S]*\})/);
    if (jsonMatch) {
      let jsonString = jsonMatch[0];

      // Truncation repair: close open brackets if missing
      const openBrackets = (jsonString.match(/\[/g) || []).length;
      const closeBrackets = (jsonString.match(/\]/g) || []).length;
      const openCurly = (jsonString.match(/\{/g) || []).length;
      const closeCurly = (jsonString.match(/\}/g) || []).length;

      if (openBrackets > closeBrackets) jsonString += ']'.repeat(openBrackets - closeBrackets);
      if (openCurly > closeCurly) jsonString += '}'.repeat(openCurly - closeCurly);

      return JSON.parse(jsonString);
    }
    throw e;
  }
}
